{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Baths & Restorative Sessions</title>
  <meta name="description" content="Clinical, calming sound bath experiences — in-person & hybrid offerings. Next event: {{NEXT_EVENT_DATE}}">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <div class="page-bg">
    <img src="assets/img/pattern.svg" alt="Subtle background pattern" class="bg-pattern">
  </div>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Our Approach</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="menu-toggle" aria-expanded="false" aria-label="Open Menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero">
      <div class="wrap hero-card glass">
        <div class="hero-left">
          <h1 class="hero-title">A guided, sensory sound bath for deep restoration</h1>
          <p class="sub">Clinical, calming sound journeys led by {{FACILITATOR_NAME}} — intimate gatherings in {{CITY}}, {{STATE}} and hybrid access for remote attendees.</p>
          <ul class="hero-list">
            <li>Premium acoustic design • Limited capacity</li>
            <li>In-person + live-stream (hybrid)</li>
            <li>Next event: <strong>{{NEXT_EVENT_DATE}}</strong></li>
          </ul>
          <div class="hero-actions">
            <a class="btn primary ripple-trigger" href="events.html">See Next Event</a>
            <a class="btn outline" href="private-sessions.html">Private & 1:1</a>
          </div>
        </div>
        <div class="hero-right">
          <div class="info glass small">
            <h4>What to expect</h4>
            <p>Quiet arrival, gentle orientation, a 45–60 minute sound journey featuring curated instruments and a short grounding close.</p>
            <a class="micro-link" href="#framework">Read the flow</a>
          </div>
          <div class="ripple-pane" aria-hidden="true"></div>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section id="story" class="story wrap">
      <div class="glass story-card">
        <h2>Why sound? A clinical, sensory approach</h2>
        <p class="lead">We weave intention, acoustic architecture, and therapeutic pacing to create a reliably restorative environment. Each session is crafted with attention to safety and accessibility.</p>
        <div class="columns">
          <div>
            <h3>Curated timbres</h3>
            <p>We rotate instruments—crystal singing bowls, a deep gong, gentle chimes, and tuning forks—for layered harmonic textures that support breath and nervous system regulation.</p>
          </div>
          <div>
            <h3>Intentional space</h3>
            <p>Our venue, {{VENUE_NAME}}, is prepared with cushioned mats, blankets, and dimmed lighting. Hybrid participants receive a pre-session protocol for optimal home listening.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK (flow, what to bring, contraindications) -->
    <section id="framework" class="framework wrap">
      <div class="glass">
        <h2>Session flow & practical notes</h2>
        <ol class="flow">
          <li><strong>Arrival & orientation (10 min)</strong> — settle in, set intentions, and get comfortable.</li>
          <li><strong>Guided breathing & easing (5–10 min)</strong> — gentle cues to arrive into body and breath.</li>
          <li><strong>Sound journey (45–60 min)</strong> — layered instruments, intentional pauses, and live modulation to support deep states.</li>
          <li><strong>Closing & reintegration (5–10 min)</strong> — soft return, journaling prompts, movement suggestions.</li>
        </ol>
        <h3>What to bring</h3>
        <ul>
          <li>Yoga mat or thick pad, blanket, eye mask, and water.</li>
          <li>For hybrid: high-quality headphones, quiet room, and comfy surface.</li>
        </ul>
        <h3>Contraindications & safety</h3>
        <p class="muted">If you are pregnant, have uncontrolled seizures, are sensitive to strong vibrations, or have recent head/ear surgery, please consult your healthcare provider before attending. Sound work is not a substitute for medical care.</p>
      </div>
    </section>

    <!-- OFFERS -->
    <section id="offers" class="offers wrap">
      <h2>Offerings (hybrid model)</h2>
      <div class="cards">
        <article class="card glass">
          <h3>Group Sound Baths</h3>
          <p>Scheduled, limited-attendance gatherings with live facilitation and optional livestream access.</p>
          <p class="meta">Instruments may include crystal bowls, monochord, and chimes.</p>
          <a class="btn" href="events.html">Upcoming Sessions</a>
        </article>
        <article class="card glass">
          <h3>Private Sessions</h3>
          <p>1:1 clinical-style sessions tuned to individual needs; also available for couples and corporate wellbeing experiences.</p>
          <p class="meta">Typical instruments: gong, tuning forks, handheld chimes.</p>
          <a class="btn" href="private-sessions.html">Private Options</a>
        </article>
        <article class="card glass">
          <h3>Corporate & Workshops</h3>
          <p>Tailored on-site or virtual programs for teams emphasizing stress resilience and mindful pauses.</p>
          <a class="btn" href="contact.html">Inquire</a>
        </article>
      </div>
    </section>

    <!-- PRICING SUMMARY -->
    <section id="pricing" class="pricing wrap">
      <div class="glass split">
        <div>
          <h2>Transparent pricing</h2>
          <p>Hybrid pricing keeps participation accessible — in-person and livestream tiers. Detailed rates and packages on the pricing page.</p>
        </div>
        <div class="price-list">
          <div class="price-item">
            <strong>$30</strong>
            <span>Livestream pass</span>
          </div>
          <div class="price-item">
            <strong>$65</strong>
            <span>In-person single</span>
          </div>
          <div class="price-item">
            <strong>Packages</strong>
            <span>Multi-session passes available</span>
          </div>
          <a class="btn outline" href="pricing.html">See full rates</a>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section id="testimonials" class="testimonials wrap">
      <h2>Client reflections</h2>
      <div class="test-cards">
        <blockquote class="glass">
          "I felt held and safe throughout — the sound design was precise and deeply calming."<footer>— A. R., regular attendee</footer>
        </blockquote>
        <blockquote class="glass">
          "Hybrid attendance was seamless; I could feel the intention across the livestream."<footer>— M. S., remote participant</footer>
        </blockquote>
        <blockquote class="glass">
          "A restorative reset. Highly curated and professional."<footer>— Corporate HR, wellness program</footer>
        </blockquote>
      </div>
    </section>

    <!-- CALL TO ACTION -->
    <section id="cta" class="cta wrap">
      <div class="glass cta-card">
        <h2>Reserve your place</h2>
        <p>Space is intentionally limited to maintain quality. Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> to book private sessions or secure a spot.</p>
        <div class="cta-actions">
          <a class="btn primary ripple-trigger" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn outline" href="events.html">View calendar</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <small>&copy; {{BUSINESS_NAME}} — Facilitated by {{FACILITATOR_NAME}} • Hosted at {{VENUE_NAME}} • {{CITY}}, {{STATE}}</small>
      <nav class="foot-nav">
        <a href="about.html">About</a>
        <a href="faq.html">FAQ</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </footer>

</body>
</html>"} 
