{"path":"assets/css/styles.css","content":"/* Glass morphism sound bath site - clinical calm */
:root{
  --bg-1:#0f1724;
  --bg-2:#0b1020;
  --accent:#9be7e0;
  --muted:#aab6c5;
  --glass-1:rgba(255,255,255,0.06);
  --glass-2:rgba(255,255,255,0.04);
  --card-radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:linear-gradient(180deg,var(--bg-1),var(--bg-2));color:#e9f3f6}
.page-bg{position:fixed;inset:0;z-index:0;overflow:hidden;opacity:0.32;mix-blend-mode:overlay}
.bg-pattern{width:130%;height:130%;object-fit:cover;filter:blur(10px);transform:translate(-10%,-6%)}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;backdrop-filter:blur(8px);background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);border-bottom:1px solid rgba(255,255,255,0.03);z-index:10}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:600;color:var(--accent);text-decoration:none}
.nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,#10707f,#42c1b8);color:#042;box-shadow:0 6px 18px rgba(10,30,40,0.35)}
.menu-toggle{display:none;background:transparent;border:none;color:var(--muted);font-size:20px}
.hero{padding:36px 0}
.hero-card{display:flex;gap:20px;align-items:stretch;padding:28px;border-radius:var(--card-radius);position:relative}
.hero-card.glass{background:linear-gradient(180deg,var(--glass-1),var(--glass-2));box-shadow:0 8px 30px rgba(3,6,10,0.5);border:1px solid rgba(255,255,255,0.04)}
.hero-left{flex:1}
.hero-title{font-size:30px;margin:0 0 12px;color:#eaffff}
.sub{color:var(--muted);margin:0 0 14px}
.hero-list{list-style:none;padding:0;margin:0 0 18px;color:var(--muted)}
.hero-actions{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;color:#e9f3f6;border:1px solid rgba(255,255,255,0.06);background:transparent}
.btn.primary{background:linear-gradient(90deg,#0bb8b2,#7adcd6);color:#022;box-shadow:0 8px 20px rgba(10,40,50,0.25)}
.btn.outline{border:1px solid rgba(255,255,255,0.08)}
.hero-right{width:320px;display:flex;flex-direction:column;gap:14px}
.info{padding:14px;border-radius:12px}
.info.small{font-size:14px}
.ripple-pane{flex:1;border-radius:12px;position:relative;overflow:hidden;background:linear-gradient(180deg,transparent,rgba(255,255,255,0.02));min-height:90px}
.ripple-pane::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at var(--rx,50%) var(--ry,50%),rgba(155,231,224,0.06),transparent 20%)}
.story{padding:30px 0}
.story-card{padding:22px;border-radius:14px}
.columns{display:flex;gap:22px}
.columns > div{flex:1}
.framework{padding:26px 0}
.flow{padding-left:18px}
.muted{color:var(--muted)}
.offers{padding:26px 0}
.cards{display:flex;gap:18px}
.card{padding:18px;border-radius:12px;flex:1}
.pricing{padding:26px 0}
.split{display:flex;justify-content:space-between;align-items:center;padding:18px}
.price-list{display:flex;flex-direction:column;gap:10px;align-items:flex-end}
.price-item{background:linear-gradient(180deg,transparent,rgba(255,255,255,0.02));padding:8px 12px;border-radius:10px}
.testimonials{padding:26px 0}
.test-cards{display:flex;gap:14px}
blockquote{padding:18px;border-radius:12px;border-left:3px solid rgba(155,231,224,0.12)}
.site-footer{padding:24px 0;color:var(--muted);border-top:1px solid rgba(255,255,255,0.02)}
.foot-nav{display:flex;gap:12px}
.micro-link{color:var(--accent);text-decoration:none}
@media (max-width:880px){
  .columns{flex-direction:column}
  .cards{flex-direction:column}
  .hero-card{flex-direction:column}
  .nav{display:none}
  .menu-toggle{display:block;margin-left:auto}
}
/* Ripple animation */
.ripple{position:absolute;border-radius:50%;transform:scale(0);pointer-events:none;background:radial-gradient(circle,#9be7e0aa,#9be7e0aa 60%,transparent 70%);opacity:0.9;animation:ripple 900ms cubic-bezier(.2,.8,.2,1)}
@keyframes ripple{to{transform:scale(6);opacity:0}}
/* subtle animated variables */
:root{--rx:50%;--ry:50%}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Ripple triggers
  function makeRipple(e){
    var rect = e.currentTarget.getBoundingClientRect();
    var x = e.clientX - rect.left;
    var y = e.clientY - rect.top;
    var r = Math.max(rect.width, rect.height);
    var el = document.createElement('span');
    el.className = 'ripple';
    el.style.left = (x - r/2) + 'px';
    el.style.top = (y - r/2) + 'px';
    el.style.width = el.style.height = r + 'px';
    e.currentTarget.appendChild(el);
    setTimeout(function(){ el.remove(); }, 950);
  }

  document.addEventListener('DOMContentLoaded', function(){
    // Attach ripple to elements with class ripple-trigger
    var triggers = document.querySelectorAll('.ripple-trigger');
    triggers.forEach(function(btn){
      btn.addEventListener('click', function(ev){
        // For anchors, show ripple on their parent container if possible
        var target = btn;
        // create a temporary ripple container if none
        if(getComputedStyle(target).position === 'static'){
          target.style.position = 'relative';
        }
        makeRipple(ev);
      });
    });

    // Nav toggle for small screens
    var toggle = document.querySelector('.menu-toggle');
    if(toggle){
      toggle.addEventListener('click', function(){
        var nav = document.querySelector('.nav');
        var expanded = this.getAttribute('aria-expanded') === 'true';
        this.setAttribute('aria-expanded', String(!expanded));
        if(nav){ nav.style.display = expanded ? 'none' : 'flex'; }
      });
    }

    // Gentle motion seeded for consistent visual
    var seed = 638947372;
    var rx = 40 + (seed % 20);
    var ry = 50 + ((seed>>2) % 20);
    document.documentElement.style.setProperty('--rx', rx + '%');
    document.documentElement.style.setProperty('--ry', ry + '%');

    // Subtle auto move of ripple-pane focus to give sense of flow
    var pane = document.querySelector('.ripple-pane');
    if(pane){
      var i=0;
      setInterval(function(){
        i = (i+1)%100;
        var x = 30 + Math.sin(i/10)*20;
        var y = 40 + Math.cos(i/14)*18;
        pane.style.setProperty('--rx', x + '%');
        pane.style.setProperty('--ry', y + '%');
      },2200);
    }
  });
})();"} 
